pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Empty _tos array will cause require(_tos.length > 0) to revert
        // We need a valid _tos with at least one element to avoid revert
        address[] memory tos = new address[](1);
        tos[0] = address(0x1234);
        // Call transfer with a non-reverting scenario
        // The correct contract returns true, the mutant returns false
        bool result = c.transfer(address(this), address(0x5678), tos, 100);
        // Reference: true. Mutant: false.
        assertTrue(result == true);
    }
}

