pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Use a call that reverts: call a non-existent contract address
        // The correct contract reverts; the mutant returns true despite the failed call.
        bool success;
        address fake = address(0xdead);
        address[] memory tos = new address[](1);
        tos[0] = address(0xbeef);
        try c.transfer(address(this), fake, tos, 100) {
            success = true;
        } catch {
            success = false;
        }
        // The correct contract reverts (success = false), but the mutant returns true (success = true)
        // Assert that success is false — this passes on reference, fails on buggy.
        assertTrue(!success);
    }
}

