pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a mock that implements transferFrom and returns false without reverting
        // We use a simple contract defined inline for the mock
        // The mock address will be used as caddress
        address mock = address(new MockToken());
        address from = address(0x123);
        address[] memory tos = new address[](1);
        tos[0] = address(0x456);
        uint v = 100;

        // Call transfer; in reference it reverts, in mutant it does not
        bool ok;
        try c.transfer(from, mock, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        // Assert that the call succeeded (which happens ONLY in the mutant)
        // The reference fails with revert, but mutant returns true
        assertTrue(ok, "transfer should have succeeded on mutant but not reference");
    }
}

// Simple mock that returns false from transferFrom
contract MockToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return false;
    }
}

