// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // We need a token contract that will revert on transferFrom
        // Deploy a simple token that always reverts
        // Then call transfer with that token address and some addresses
        // For reference: call reverts -> returns false; bug: ignores revert -> returns true

        // Deploy a token that reverts on any call
        RevertingToken token = new RevertingToken();
        address[] memory tos = new address[](1);
        tos[0] = address(0x1234);

        // Try-catch to capture revert
        bool ok;
        try c.transfer(address(this), address(token), tos, 100) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: reverts (ok = false), bug: ignores (ok = true)
        assertTrue(!ok, "Expected revert due to token failure");
    }
}

contract RevertingToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("always fail");
    }
}

